<script lang="ts">
	import { rhythmGame, NOTE_TRAVEL_MS, NOTE_LINGER_MS, hitLineCenterPx } from './rhythm-state.svelte';
	import type { Column } from './chart';

	// laneHeightPx and barHeightPx come from the parent (PlayerCircles.svelte),
	// which measures the shared lanes row and sizes the one shared hit bar -
	// every player's lane uses those same two numbers, so there's nothing
	// left for this component to measure or compute itself.
	let { player, laneHeightPx, barHeightPx }: { player: number; laneHeightPx: number; barHeightPx: number } =
		$props();

	const COLUMNS: { key: Column }[] = [{ key: 'arrows' }, { key: 'ab' }];

	// Notes are colored by character, not by column - see SLOTS in
	// PlayerCircles.svelte for the same player-number order.
	const PLAYER_NOTE_COLOR: Record<number, string> = {
		1: 'var(--color-purple)', // Bing / cat
		2: 'var(--color-yellow)', // Bong / chicken
		3: 'var(--color-orange)', // Ping / goose
		4: 'var(--color-pink)' // Pong / ostrich
	};
	const noteColor = $derived(PLAYER_NOTE_COLOR[player] ?? 'var(--color-purple)');

	// A note at progress 1 (the instant it's actually judged) is placed at
	// the hit bar's vertical center, not the lane's bottom edge - otherwise
	// a press timed to when the note visually sits inside the bar can land
	// outside the real timing window and silently do nothing (see
	// hitLineCenterPx's doc comment).
	const hitLineTopPx = $derived(hitLineCenterPx(laneHeightPx));

	// arrow.svg points up with no rotation - rotate it clockwise for the
	// other three directions.
	const ARROW_ROTATION: Record<string, number> = { U: 0, R: 90, D: 180, L: 270 };

	function progressFor(noteTimeSec: number, atMs: number = rhythmGame.nowMs) {
		return (atMs - (noteTimeSec * 1000 - NOTE_TRAVEL_MS)) / NOTE_TRAVEL_MS;
	}

	// progress === 1 is the instant a press would be judged "perfect" (see
	// classify() in judgment.ts, centered on note.time). The hit bar is
	// bottom-anchored, so without this offset that instant lands the note's
	// center on the bar's bottom edge, not its middle - pulling every note's
	// target up by half the bar's height puts the judged moment where the
	// note visually looks centered in the bar, which is what actually
	// reads as "on the beat".
	function topPxFor(progress: number) {
		return progress * laneHeightPx - barHeightPx / 2;
	}

	// A missed note stays fully dim while it falls past the bar and the
	// characters, then fades the rest of the way out over the tail end of
	// its lingering window, timed to reach 0 right as it's actually removed
	// (see NOTE_LINGER_MS) - so it never just pops out of existence.
	const MISS_FADE_START_MS = NOTE_LINGER_MS * 0.55;
	function missOpacity(resolvedAtMs: number) {
		const age = rhythmGame.nowMs - resolvedAtMs;
		if (age <= MISS_FADE_START_MS) return 0.35;
		const fadeProgress = (age - MISS_FADE_START_MS) / (NOTE_LINGER_MS - MISS_FADE_START_MS);
		return Math.max(0, 0.35 * (1 - fadeProgress));
	}

	// Deterministic per-note wobble (seeded by id, not by frame) so a note's
	// path is fixed and gentle rather than a perfectly straight line or a
	// jittery random walk.
	function wobbleFor(id: number, progress: number) {
		const seed = (id * 2654435761) % 1000;
		const amplitude = 1 + (seed % 2); // 1-2px - barely perceptible
		const speed = 1.5 + (seed % 5) / 5; // 1.5-2.5 cycles over the fall
		return Math.sin(progress * Math.PI * 2 * speed + seed) * amplitude;
	}
</script>

