						? 'grayscale'
						: ''} {isHit ? 'hit-flash' : ''}"
					style="top: {progress * hitLineTopPx}px; left: calc(50% + {wobbleFor(
						n.id,
						progress
					)}px); transform: translate(-50%, -50%) scale({burstScale}); opacity: {isMiss
