			<div class="milestone-pop pointer-events-none absolute inset-x-0 top-1/3 flex justify-center">
				<span
					class="font-cloud text-2xl text-yellow text-shadow-gray-800 text-shadow-sm lg:text-4xl"
				>
					{rhythmGame.milestoneFeedback.get(player)?.text}
				</span>
			</div>
		{/if}
	{/key}
</div>

<style>
	/* A hit needs to read as "caught", not just "shrinking away" - a sharp
	   brightness spike that immediately decays, layered under the
	   transform/scale burst set inline above. --flash-peak (set per-note,
	   higher for perfect) is what makes perfect hits flash brighter than
	   good ones. Runs as a keyframe animation rather than a transition so it
	   always starts fresh at full brightness regardless of the note's
	   previous state. */
	@keyframes hit-flash {
		0% {
			opacity: 1;
			filter: brightness(var(--flash-peak, 1.7)) saturate(1.4);
		}
		100% {
			opacity: 0;
			filter: brightness(1);
		}
	}

	.hit-flash {
		animation: hit-flash 300ms ease-out forwards;
	}

	/* Pops in, holds, then fades - lasts the same 900ms as
	   MILESTONE_DISPLAY_MS in rhythm-state.svelte.ts so it's gone from the
	   DOM right as the animation would otherwise sit on its end state. */
	@keyframes milestone-pop {
		0% {
			transform: scale(0.5);
			opacity: 0;
		}
		15% {
			transform: scale(1.15);
			opacity: 1;
		}
		25% {
			transform: scale(1);
			opacity: 1;
		}
		80% {
			transform: scale(1);
			opacity: 1;
		}
		100% {
			transform: scale(1.05);
			opacity: 0;
		}
	}

	.milestone-pop {
		animation: milestone-pop 900ms ease-out forwards;
	}
</style>
